[
  {
    "incident": {
      "component": "web-03 (filesystem)",
      "category": "resource_exhaustion",
      "status": "firing",
      "summary": "Critical inode exhaustion on web-03 root filesystem with only 1% inodes remaining."
    },
    "assessment": {
      "urgency": "critical",
      "rationale": "Inode exhaustion prevents the creation of new files even if disk space is available, which will cause application failures (e.g., PHP session creation) and system instability."
    },
    "facts": [
      "Alert: NodeFilesystemFilesFillingUp",
      "Instance: web-03:9100",
      "Mountpoint: /",
      "Filesystem type: ext4",
      "Inodes free: 1%",
      "Disk usage: 40%",
      "Filesystem size: 100GiB",
      "Filesystem available: 60GiB",
      "Context: App writes PHP session files to /var/lib/php/sessions"
    ],
    "missing_context": [
      {
        "item": "Inode usage breakdown",
        "why": "To identify which directory contains the most files",
        "how_to_check": "find / -xdev -printf '%h\n' | sort | uniq -c | sort -k1 -rn | head -n 20"
      },
      {
        "item": "Rate of inode consumption",
        "why": "To determine if this is a sudden spike or a slow leak",
        "how_to_check": "Prometheus query: rate(node_filesystem_files_free[15m])"
      }
    ],
    "immediate_actions": [
      {
        "action": "Identify and clean up old PHP session files",
        "purpose": "Free up inodes immediately to restore service functionality",
        "conditions": "If /var/lib/php/sessions is the primary consumer",
        "expected_effect": "Increase in available inodes",
        "risks": "Deleting active sessions may log out current users",
        "requires_approval": false,
        "verify": "df -i /",
        "rule_ids": [
          "CLEANUP_STALE_FILES"
        ]
      }
    ],
    "investigation_steps": [
      {
        "step": "Check directory with highest file count",
        "hypothesis": "The PHP session directory or a log directory is saturated with small files",
        "how_to_check": "du --inodes -S / | sort -rh | head -n 10"
      },
      {
        "step": "Check for deleted files still held open by processes",
        "hypothesis": "Large number of deleted files are still consuming inodes because processes haven't closed them",
        "how_to_check": "lsof +L1"
      }
    ],
    "root_cause_hypotheses": [
      "PHP session cleanup (garbage collection) is not running or is failing",
      "Application is creating an excessive number of small temporary files",
      "Log rotation is failing, leading to many small rotated log files"
    ],
    "dangerous_operations": [
      {
        "operation": "rm -rf /var/lib/php/sessions/*",
        "why_dangerous": "Could cause widespread user logout and potential application errors if files are currently being written",
        "rule_id": "DATA_LOSS_PREVENTION"
      }
    ],
    "applied_expert_rules": [
      "INODE_EXHAUSTION_PROTOCOL"
    ],
    "incident_update": "🚨 *Critical Alert: web-03 Inode Exhaustion* 🚨\nFilesystem `/` on `web-03` is at 1% inode capacity. Disk space is fine (40% used), but inode depletion will block file creation. Investigating `/var/lib/php/sessions` as the likely culprit. Updates to follow."
  }
]
